const ConsentForm = () => {
  const [agreed, setAgreed] = useState(false);
  const [error, setError] = useState(false);
  const checkboxRef = useRef(null);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!agreed) {
      setError(true);
      checkboxRef.current.focus();
    } else {
      setError(false);
      alert('Form submitted successfully!');
    }
  };

  const handleCheckboxChange = (e) => {
    setAgreed(e.target.checked);
    if (e.target.checked) {
      setError(false);
    }
  };

  return (
  <div className="card">
    <main id="main-content">
      <h1>Create Account</h1>
      <form onSubmit={handleSubmit} noValidate>
        <div className="form-field">
          <div className="checkbox-wrapper">
            <input
              id="consent-checkbox"
              type="checkbox"
              required
              checked={agreed}
              onChange={handleCheckboxChange}
              ref={checkboxRef}
              aria-describedby="consent-helper consent-error"
              aria-invalid={error}
            />
            <label htmlFor="consent-checkbox">
              I agree to the <a href="#">Terms of Use</a>
              <span className="required-marker" aria-hidden="true">*</span>
              <span className="sr-only">(required)</span>
            </label>
          </div>
          <p id="consent-helper" className="helper-text">
            You must agree to our terms before creating an account.
          </p>
          {error && (
            <p id="consent-error" className="error-message" style={{ display: 'block' }}>
              Error: You must check this box to proceed.
            </p>
          )}
        </div>
        <button type="submit">
          Sign Up
        </button>
      </form>
    </main>
  </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<ConsentForm />);
