  background-color: var(--bg-color);
  color: var(--text-color);
  margin: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 20px;
}

.card {
  background-color: var(--card-bg);
  padding: 32px;
  border-radius: 8px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
  width: 100%;
  max-width: 400px;
}

h1 {
  font-size: 1.5rem;
  margin-top: 0;
  margin-bottom: 24px;
}

.form-field {
  margin-bottom: 24px;
}

.checkbox-wrapper {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

input[type="checkbox"] {
  width: 20px;
  height: 20px;
  margin-top: 2px;
  cursor: pointer;
  accent-color: var(--primary-color);
}

label {
  font-size: 1rem;
  cursor: pointer;
  line-height: 1.4;
}

.required-marker {
  color: var(--error-color);
  margin-left: 2px;
}

.helper-text {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-top: 8px;
  margin-left: 32px; /* Align with label text, assuming 20px checkbox + 12px gap */
}

.error-message {
  font-size: 0.875rem;
  color: var(--error-color);
  margin-top: 8px;
  margin-left: 32px;
  display: none;
}

input:invalid:not(:placeholder-shown) ~ .error-message {
  display: block;
}

a {
  color: var(--primary-color);
  text-decoration: underline;
  border-radius: 2px;
}

a:hover {
  color: var(--primary-hover);
}

a:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

button[type="submit"] {
  width: 100%;
  background-color: var(--primary-color);
  color: white;
  border: none;
  padding: 12px 24px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.2s ease;
}

button[type="submit"]:hover {
  background-color: var(--primary-hover);
}

button[type="submit"]:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

/* Screen reader only */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

.sr-only-focusable:focus {
  position: static;
  width: auto;
  height: auto;
  padding: 10px;
  margin: 0;
  overflow: visible;
  clip: auto;
  white-space: normal;
  background: white;
  color: var(--primary-color);
  z-index: 100;
  display: block;
}
