const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // Load the local HTML file
  const filePath = path.resolve(__dirname, 'index.html');
  const fileUrl = `file://${filePath}`;

  await page.goto(fileUrl, { waitUntil: 'networkidle' });

  // Wait for React to render the h1
  await page.waitForSelector('h1', { timeout: 5000 }).catch(() => console.error('H1 not found'));

  // Inject axe-core
  const axeSource = fs.readFileSync(path.join(__dirname, 'axe.min.js'), 'utf8');
  await page.evaluate(axeSource);

  // Run axe
  const results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  await browser.close();

  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = results.violations.filter(v => v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
    bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
  }, null, 2));

  if (wcag.length > 0) {
    process.exit(1);
  }
})();
